// [MEDIUM_PRIORITY] RESOURCE_SECURITY: Cipher mode appropriate
// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.unifiedimport timber.log.Timberimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.memory.MemoryTypeimport com.roshan.persona.connectivity.model.CommsEntryimport com.roshan.persona.connectivity.model.CommsTypeimport com.roshan.persona.connectivity.model.CallDirectionimport com.roshan.persona.connectivity.model.MessagingAppimport com.roshan.persona.connectivity.call.CallLogServiceimport com.roshan.persona.connectivity.call.CallLogEntryimport com.roshan.persona.connectivity.sms.SmsHistoryServiceimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsDirectionimport com.roshan.persona.connectivity.model.CommsInsightimport com.roshan.persona.connectivity.model.InsightTypeimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.withContextimport java.time.Instantimport java.util.concurrent.ConcurrentHashMapimport kotlin.math.abs/** * NOUS — Messaging Unification Engine (Module 11 v3 — Step 11.7). * * Unified inbox for SMS + WhatsApp + Telegram + Signal via * NotificationListenerService. Reads incoming messages from ALL messaging * apps in one place. * * ## How it works (per strategy v3 §"MessagingUnificationEngine") * * **Inbound**: [NotificationListenerInterface] receives notifications from * WhatsApp/Telegram/Signal. The engine parses them into [UnifiedMessage] * objects and emits via [incomingMessages] Flow. * * **Unified inbox**: All messages (SMS + WhatsApp + Telegram) are merged * into a single timeline via [CommsHistoryEngine]. * * ## Episodic memory persistence * * Strategy §"CommsHistoryEngine" requires every message to be written to * Module 3 (Memory) — encrypted automatically. [recordMessage] delegates * to [MemoryInterface.store] which writes via [com.roshan.persona.memory.repository.EpisodicMemoryRepository] * (Room + SQLCipher). * * ## Privacy * *  - Messages are read ephemerally via NotificationListener — NOT stored *    permanently (only the latest notification per app is kept in memory). *  - Episodic memory entries are encrypted at rest (SQLCipher AES-256-CBC). *  - User must explicitly enable notification access in Settings. *  - No message content is sent to any server. *  - User can disable per-app (WhatsApp ON, Telegram OFF, etc.). * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§MessagingUnificationEngine</a> */class MessagingUnificationEngine(    private val notificationListener: NotificationListenerInterface,    private val dispatcher: CoroutineDispatcher,    private val memory: MemoryInterface? = null,) {    /** Hot stream of incoming messages from all apps. */    private val _incomingMessages = MutableSharedFlow<UnifiedMessage>(extraBufferCapacity = 64)    val incomingMessages: Flow<UnifiedMessage> = _incomingMessages.asSharedFlow()    /** Latest message per app (for "unread" count). */    private val latestByApp = ConcurrentHashMap<MessagingApp, UnifiedMessage>()    /**     * Process an incoming notification from a messaging app.     *     * Called by [NotificationListenerInterface] when a new notification arrives.     *     * @param app which messaging app sent the notification.     * @param sender the sender's name (from notification title).     * @param body the message body (from notification text).     * @param recipient the local user's identifier on this app (null for SMS —     *   recipient is implicit).     */    suspend fun processIncomingNotification(        app: MessagingApp,        sender: String,        body: String,        recipient: String? = null,    ) = withContext(dispatcher) {        val message = UnifiedMessage(            id = "msg_${System.currentTimeMillis()}_${app.name}",            app = app,            senderName = sender,            recipient = recipient,            body = body,            timestampMs = System.currentTimeMillis(),            isRead = false,        )        latestByApp[app] = message        _incomingMessages.emit(message)        // Persist to episodic memory (encrypted at rest via SQLCipher).        recordMessage(message)        Timber.tag(TAG).d("Incoming ${app.displayLabel} from $sender: ${body.take(50)}...")    }    /**     * Persist a [message] to Module 3 episodic memory (encrypted).     *     * Strategy §"CommsHistoryEngine": "encrypted in episodic memory".     * Calls [MemoryInterface.store] which routes through the encrypted     * Room DAO. Failure is logged but does NOT propagate — memory     * persistence is best-effort.     */    suspend fun recordMessage(message: UnifiedMessage) {        val mem = memory ?: return        try {            val memory = Memory(                type = MemoryType.EPISODIC,                content = "[${message.app.displayLabel}] ${message.senderName}: ${message.body}",                timestamp = Instant.ofEpochMilli(message.timestampMs),                importance = 0.4f, // routine comms — low-importance default                tags = setOf("comms", message.app.name.lowercase()),            )            mem.store(memory)        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "recordMessage: episodic memory store failed")        }    }    /**     * Get unread messages from all apps.     */    fun getUnread(): List<UnifiedMessage> = latestByApp.values.filter { !it.isRead }    /**     * Mark a message as read.     */    fun markAsRead(app: MessagingApp) {        latestByApp[app]?.let { latestByApp[app] = it.copy(isRead = true) }    }    /**     * Get unread count per app.     */    fun getUnreadCounts(): Map<MessagingApp, Int> {        return MessagingApp.entries.associateWith { app ->            if (latestByApp[app]?.isRead == false) 1 else 0        }    }    /**     * Check if notification listener is enabled.     */    fun isListenerEnabled(): Boolean = notificationListener.isEnabled()    private companion object {        private const val TAG = "MessagingUnify"    }}// ──────────────────────────────────────────────────────────────────────────/** * One message from any messaging app (unified format). * * @param recipient the local user's identifier on this app (phone number for *   WhatsApp, username for Telegram, null for SMS where recipient is implicit). *   Strategy §"UnifiedMessage" requires this field. */data class UnifiedMessage(    val id: String,    val app: MessagingApp,    val senderName: String,    val body: String,    val timestampMs: Long,    val isRead: Boolean,    val recipient: String? = null,)/** * Interface for Android's NotificationListenerService. * * Real implementation wraps NotificationListenerService and parses * notifications from WhatsApp/Telegram/Signal. Tests inject a fake. */interface NotificationListenerInterface {    /** True if the notification listener is enabled (user granted access). */    fun isEnabled(): Boolean}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Comms History Engine (Module 11 v3 — Step 11.7). * * Unified timeline of all communications (calls + SMS + WhatsApp + Telegram) * with deep search and behavioral insights. * * ## Features * *  - **Unified timeline** — merge calls + SMS into one chronological list. *  - **Deep search** — "show all messages containing 'flight' from Mom". *  - **Insights** — "You talk to Mom 5× more than Dad". * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§CommsHistoryEngine</a> */class CommsHistoryEngine(    private val callLogService: CallLogService,    private val smsHistoryService: SmsHistoryService,    private val dispatcher: CoroutineDispatcher,    private val memory: MemoryInterface? = null,) {    /**     * Record a [UnifiedMessage] to episodic memory (Module 3, encrypted).     *     * Strategy §"CommsHistoryEngine": "encrypted in episodic memory" — every     * message that flows through the unified inbox is also persisted via     * [MemoryInterface.store], which writes to the encrypted Room DAO.     *     * Failure is logged but does NOT propagate — memory persistence is     * best-effort and should never block the user-facing message flow.     */    suspend fun recordMessage(message: UnifiedMessage) {        val mem = memory ?: return        try {            val memoryRecord = Memory(                type = MemoryType.EPISODIC,                content = "[${message.app.displayLabel}] ${message.senderName} → ${message.recipient ?: "me"}: ${message.body}",                timestamp = Instant.ofEpochMilli(message.timestampMs),                importance = 0.4f,                tags = setOf("comms", message.app.name.lowercase()),            )            mem.store(memoryRecord)        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "recordMessage: episodic memory store failed")        }    }    /**     * Get the unified comms timeline.     *     * @param sinceMs only entries after this timestamp.     * @param limit max entries.     * @return merged timeline (calls + SMS), most-recent-first.     */    suspend fun getTimeline(sinceMs: Long = 0, limit: Int = 100): List<CommsEntry> = withContext(dispatcher) {        val calls = callLogService.getCallLog(sinceMs).map { it.toCommsEntry() }        val sms = smsHistoryService.getSmsHistory(sinceMs).map { it.toCommsEntry() }        (calls + sms).sortedByDescending { it.timestampMs }.take(limit)    }    /**     * Search across all comms (calls + SMS).     *     * @param query the search query.     * @param limit max results.     * @return matching entries.     */    suspend fun search(query: String, limit: Int = 50): List<CommsEntry> = withContext(dispatcher) {        val lower = query.lowercase().trim()        val timeline = getTimeline(0, Int.MAX_VALUE)        timeline.filter { entry ->            entry.summary.lowercase().contains(lower) ||                entry.phoneNumber.contains(lower) ||                entry.contact?.displayName?.lowercase()?.contains(lower) == true        }.take(limit)    }    /**     * Get comms for a specific contact.     */    suspend fun getCommsForContact(phoneNumber: String, limit: Int = 50): List<CommsEntry> = withContext(dispatcher) {        val calls = callLogService.getCallLog(0).filter { it.phoneNumber == phoneNumber }.map { it.toCommsEntry() }        val sms = smsHistoryService.getSmsForContact(phoneNumber, 0).map { it.toCommsEntry() }        (calls + sms).sortedByDescending { it.timestampMs }.take(limit)    }    /**     * Generate comms insights (behavioral analytics).     *     * "You talk to Mom 5× more than Dad."     * "Your average call is 5 minutes."     * "You reply to Priya in 2 min but take 6 hours for Rohit."     */    suspend fun generateInsights(): List<CommsInsight> = withContext(dispatcher) {        val insights = mutableListOf<CommsInsight>()        val calls = callLogService.getCallLog(0)        // Call frequency per contact.        val byContact = calls.groupBy { it.displayName ?: it.phoneNumber }        if (byContact.size >= 2) {            val sorted = byContact.entries.sortedByDescending { it.value.size }            val top = sorted[0]            val second = sorted[1]            val ratio = top.value.size.toFloat() / second.value.size.coerceAtLeast(1)            if (ratio >= 3f) {                insights.add(CommsInsight(                    type = InsightType.FREQUENCY,                    description = "You talk to ${top.key} ${ratio.toInt()}× more than ${second.key}.",                    confidence = 0.85f,                ))            }        }        // Average call duration.        if (calls.isNotEmpty()) {            val avgDuration = calls.map { it.durationSeconds }.average().toLong()            insights.add(CommsInsight(                type = InsightType.USAGE_PATTERN,                description = "Your average call duration is ${avgDuration / 60} min ${avgDuration % 60} sec.",                confidence = 0.9f,            ))        }        // Response time analysis (SMS).        val sms = smsHistoryService.getSmsHistory(0)        if (sms.isNotEmpty()) {            val incomingByContact = sms.filter { it.direction == SmsDirection.INCOMING }                .groupBy { it.phoneNumber }            val responseTimes = mutableMapOf<String, Long>() // contact → avg response time (ms)            for ((phone, messages) in incomingByContact) {                val sorted = messages.sortedBy { it.timestampMs }                var totalResponseMs = 0L                var count = 0                for (msg in sorted) {                    // Find the next outgoing message after this incoming one.                    val reply = sms.firstOrNull {                        it.phoneNumber == phone &&                            it.direction == SmsDirection.OUTGOING &&                        it.timestampMs > msg.timestampMs                    }                    if (reply != null) {                        totalResponseMs += (reply.timestampMs - msg.timestampMs)                        count++                    }                }                if (count > 0) {                    responseTimes[phone] = totalResponseMs / count                }            }            if (responseTimes.size >= 2) {                val fastest = responseTimes.minByOrNull { it.value }                val slowest = responseTimes.maxByOrNull { it.value }                if (fastest != null && slowest != null && fastest.key != slowest.key) {                    val fastestMin = fastest.value / 60000                    val slowestMin = slowest.value / 60000                    insights.add(CommsInsight(                        type = InsightType.RESPONSE_TIME,                        description = "You reply to ${fastest.key} in ${fastestMin}m but take ${slowestMin}m for ${slowest.key}.",                        confidence = 0.75f,                    ))                }            }        }        insights    }    // ─── Extension: convert to CommsEntry ──────────────────────────────────    private fun CallLogEntry.toCommsEntry() = CommsEntry(        id = "call_$id",        type = CommsType.CALL,        contact = null,        phoneNumber = phoneNumber,        summary = "${direction.displayLabel} ${displayName ?: phoneNumber} (${durationSeconds / 60}m)",        timestampMs = timestampMs,        direction = direction,    )    private fun SmsMessage.toCommsEntry() = CommsEntry(        id = "sms_$id",        type = CommsType.SMS,        contact = contact,        phoneNumber = phoneNumber,        summary = "${if (direction == SmsDirection.INCOMING) "From" else "To"} ${contact?.displayName ?: phoneNumber}: ${body.take(50)}",        timestampMs = timestampMs,        direction = if (direction == SmsDirection.INCOMING) CallDirection.INCOMING else CallDirection.OUTGOING,    )    private companion object {        private const val TAG = "CommsHistory"    }}